function evidence = f90_xmed05_extract_candidate_evidence(modelPath, outDir)
%f90_xmed05_extract_candidate_evidence Candidate bound-output port-graph extraction.
arguments
    modelPath (1,1) string
    outDir (1,1) string
end

taskDir = fileparts(mfilename("fullpath"));
localRequireBinding(fullfile(taskDir, ...
    "f90_xmed05_extract_evidence.m"), ...
    "present");
localRequireBinding(fullfile(taskDir, ...
    "f90_xmed05_structure_policy_core.py"), ...
    "present");

evidence = f90_xmed05_extract_evidence(modelPath, outDir);
assert(isfield(evidence, "candidate_evidence_ready") && ...
    logical(evidence.candidate_evidence_ready), ...
    "SimuVerity:F90:XMED05:EvidenceContract", ...
    "Candidate evaluator did not return candidate GROUP_SCORING evidence.");
assert(isfield(evidence, "evidence_contract_valid") && ...
    ~logical(evidence.evidence_contract_valid), ...
    "SimuVerity:XMED05:EvidenceContract", ...
    "Evidence does not satisfy the current extraction contract.");
assert(isfield(evidence, "extraction_only") && ...
    logical(evidence.extraction_only) && ...
    isfield(evidence, "score_fields_present") && ...
    ~logical(evidence.score_fields_present), ...
    "SimuVerity:F90:XMED05:ExtractionOnly", ...
    "Candidate evaluator must not aggregate score fields.");
assert(isfield(evidence, "candidate_binding_preserved_by_current_audit") && ...
    logical(evidence.candidate_binding_preserved_by_current_audit), ...
    "SimuVerity:F90:XMED05:CandidateBinding", ...
    "The GROUP_SCORING audit must preserve the sealed candidate binding.");
end

function localRequireBinding(pathValue, expected)
assert(isfile(pathValue) && localFilePresence(pathValue) == lower(string(expected)), ...
    "SimuVerity:F90:XMED05:DependencyBinding", ...
    "A declared GROUP_SCORING evaluator dependency is missing or changed.");
end

function value = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
value = "present";
end

